// A CSV value: wrapped in double quotes (any quote inside doubled) when it holds a comma, a quote
// or a line break.
const csvValue = (v: string) => (/[",\r\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);

// Downloads `lines` as a CSV file named `name`, each line ending with a line feed.
export function downloadCsv(name: string, lines: string[][]) {
  const csv = lines.map((l) => l.map(csvValue).join(',') + '\n').join('');
  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
  const a = document.createElement('a');
  a.href = url;
  a.download = name;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
import { SheetBody } from '../../slots/defs/sheetBody';
import { useClaims } from '../claims/claims';
import { gradeOn, liveHolds, usePeople } from '../people/people';
import { claimDue, heldParts, personDueTotal, rateOn, useRates } from '../rates/rates';
import { periodOf, personPeriodCarried, personPeriodDueTotal, usePeriods } from '../periods/periods';
import { useCap, useFloor, useLate } from '../access/access';
import { useSheetToday } from '../sheet/sheet';
import { getJson } from '../../api/http';
import type { Pool } from '../pools/pools';
import { downloadCsv } from './csv';
import { useCutTotals } from '../pools/pools';

// Downloads the people as a CSV file: a header line, then one line per person in list order,
// retired people included, with the grade in force today, the retired-from date ('' when not
// retired) and the due-total as the list shows it. Lines end with a line feed. While an as-of date
// is set every figure is as of it, as the list shows it then; while a preview date is set every
// figure is the preview figure, that date standing in for the sheet's today, as the list shows it.
function ExportPeople({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);
  const cutOf = useCutTotals(sheetId);

  const download = () => {
    const lines = [['name', 'grade', 'retired-from', 'due-total']];
    for (const p of people) {
      const own = claims.filter((c) => c.personId === p.id);
      lines.push([p.name, p.grade, p.retiredFrom, personDueTotal(rates, p.grades, today, own, liveHolds(p, today), floor, late, cap, heldParts(p.id, people, claims, rates, today, floor, late), cutOf(p.id))]);
    }
    downloadCsv(`people-${sheetId}.csv`, lines);
  };

  return (
    <p>
      <button type="button" data-testid="export-people" onClick={download}>
        Export people (CSV)
      </button>
    </p>
  );
}

// Downloads the claims as a CSV file: a header line, then one line per claim, people in list order
// (retired people included) and each person's claims oldest first, with the number, due and period
// as the claim's row shows them (preview figures while a preview date is set). Quoted and ended as
// the people export.
function ExportClaims({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const periods = usePeriods(sheetId).data ?? [];
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);

  const download = () => {
    const lines = [['person', 'number', 'date', 'amount', 'due', 'status', 'period']];
    for (const p of people) {
      // The sheet's claims come newest first.
      const own = claims.filter((c) => c.personId === p.id).reverse();
      for (const c of own) {
        const grade = gradeOn(p.grades, c.date);
        const due = claimDue(c, rateOn(rates, grade, c.date, c.id), floor, late, grade);
        lines.push([p.name, c.number, c.date, c.amount, due, c.status, periodOf(periods, c.dueBy)?.name ?? '']);
      }
    }
    downloadCsv(`claims-${sheetId}.csv`, lines);
  };

  return (
    <p>
      <button type="button" data-testid="export-claims" onClick={download}>
        Export claims (CSV)
      </button>
    </p>
  );
}

// Downloads the pools as a CSV file: a header line, then one line per member, pools in the order
// added and each pool's members in the order added, a member pool as pool:<name> and the cut as
// the pool's row shows it ('' when none). Quoted and ended as the people export. The pools are read
// afresh when pressed, so a change just made is always in the file; while an as-of date is set they
// are read as of it (members, pot and cuts as they stood then), and while a preview date is set they
// are read at it.
function ExportPools({ sheetId }: { sheetId: string }) {
  const download = async () => {
    const { pools } = await getJson<{ pools: Pool[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`);
    const lines = [['pool', 'member', 'share', 'cut']];
    for (const p of [...pools].sort((a, b) => a.added - b.added)) {
      for (const m of p.members) {
        lines.push([p.name, m.memberPool ? `pool:${m.memberPool}` : m.name, m.share, m.cut]);
      }
    }
    downloadCsv(`pools-${sheetId}.csv`, lines);
  };

  return (
    <p>
      <button type="button" data-testid="export-pools" onClick={() => void download()}>
        Export pools (CSV)
      </button>
    </p>
  );
}

// Downloads the period figures as a CSV file: a header line, then one line per person and period,
// people in list order (retired people included) and periods in the order added, with the figure
// and carried figure as the person's row shows them. Quoted and ended as the people export.
function ExportPeriods({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const periods = usePeriods(sheetId).data ?? [];
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);

  const download = () => {
    const lines = [['person', 'period', 'figure', 'carried']];
    const added = [...periods].sort((a, b) => a.added - b.added);
    for (const p of people) {
      for (const period of added) {
        lines.push([
          p.name,
          period.name,
          personPeriodDueTotal(period, p, claims, rates, floor, late),
          personPeriodCarried(period, periods, p, claims, rates, floor, late),
        ]);
      }
    }
    downloadCsv(`periods-${sheetId}.csv`, lines);
  };

  return (
    <p>
      <button type="button" data-testid="export-periods" onClick={download}>
        Export periods (CSV)
      </button>
    </p>
  );
}

export const contributions = [
  SheetBody.fill({ order: 2, Component: ExportPeople }),
  SheetBody.fill({ order: 2.1, Component: ExportClaims }),
  SheetBody.fill({ order: 2.2, Component: ExportPools }),
  SheetBody.fill({ order: 2.3, Component: ExportPeriods }),
];
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation } from '@tanstack/react-query';
import { SheetBody } from '../../slots/defs/sheetBody';
import { searchTree } from './treeSearch';
import type { Found } from './treeSearch';

// The tree search: a box and a button list everyone, over this sheet and every other sheet of its
// tree, whose name or an alias holds the typed text (case ignored; blank: everyone), one line each
// as <sheet id> <name> <due-total>, this sheet's people first in list order, then the other sheets'
// by sheet id. Always read fresh; the count is cleared while it runs.
function TreeSearch({ sheetId }: { sheetId: string }) {
  const [text, setText] = useState('');
  const [found, setFound] = useState<Found[] | null>(null);
  const [error, setError] = useState('');

  const search = useMutation({
    mutationFn: (t: string) => searchTree(sheetId, t),
    onSuccess: setFound,
    onError: () => setError('The search could not be run.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setFound(null);
    setError('');
    search.mutate(text.trim());
  };

  return (
    <section data-testid="tree-search">
      <form onSubmit={submit}>
        <label>
          Search the tree{' '}
          <input
            data-testid="search-name"
            value={text}
            onChange={(e) => {
              setText(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="search" disabled={search.isPending}>
          Search
        </button>
        {found !== null && (
          <>
            {' '}Found <span data-testid="search-count">{found.length}</span>
            <ul>
              {found.map((f, i) => (
                <li key={i} data-testid="search-line">
                  {f.sheetId} {f.name} {f.dueTotal}
                </li>
              ))}
            </ul>
          </>
        )}
        {error && (
          <p role="alert" data-testid="search-error">
            {error}
          </p>
        )}
      </form>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 2.5, Component: TreeSearch });
import { getJsonNow } from '../../api/http';
import type { Claim } from '../claims/claims';
import { liveHolds, nameWithGrade } from '../people/people';
import type { Person } from '../people/people';
import { heldParts, personDueTotal } from '../rates/rates';
import type { Rate } from '../rates/rates';
import { floorOf, lateOf } from '../access/access';
import type { Settings } from '../access/access';
import type { Sheet } from '../sheet/sheet';
import { cutTotal } from '../pools/pools';
import type { Pool } from '../pools/pools';

/** One person found: their sheet, their name with their grade and their due-total as their sheet's list shows it. */
export type Found = { sheetId: string; name: string; dueTotal: string };

const enc = encodeURIComponent;

/** Whether the person's name or one of their aliases holds the text, case ignored. */
function matches(p: Person, text: string): boolean {
  const t = text.toLowerCase();
  return [p.name, ...p.aliases].some((n) => n.toLowerCase().includes(t));
}

/** The people on one sheet matching the text, in list order, each read fresh from the store. */
async function searchSheet(sheetId: string, text: string): Promise<Found[]> {
  const [sheet, people, claims, rates, settings, pools] = await Promise.all([
    getJsonNow<Sheet>(`/api/sheets/${enc(sheetId)}`),
    getJsonNow<{ people: Person[] }>(`/api/sheets/${enc(sheetId)}/people`).then((r) => r.people),
    getJsonNow<{ claims: Claim[] }>(`/api/sheets/${enc(sheetId)}/claims`).then((r) => r.claims),
    getJsonNow<{ rates: Rate[] }>(`/api/sheets/${enc(sheetId)}/rates`).then((r) => r.rates),
    getJsonNow<Settings>(`/api/sheets/${enc(sheetId)}/settings`),
    getJsonNow<{ pools: Pool[] }>(`/api/sheets/${enc(sheetId)}/pools`).then((r) => r.pools),
  ]);
  const today = sheet.today;
  const floor = floorOf(settings);
  const late = lateOf(settings, today);
  const cap = settings.cap ?? '';
  return people
    .filter((p) => matches(p, text))
    .map((p) => ({
      sheetId,
      name: nameWithGrade(p),
      dueTotal: personDueTotal(rates, p.grades, today, claims.filter((c) => c.personId === p.id), liveHolds(p, today), floor, late, cap, heldParts(p.id, people, claims, rates, today, floor, late), cutTotal(pools, p.id)),
    }));
}

/**
 * Everyone over the sheet and the other sheets of its tree (its ancestors and descendants) whose
 * name or an alias holds the text, case ignored: the sheet's own people first in list order, then
 * the other sheets' by sheet id.
 */
export async function searchTree(sheetId: string, text: string): Promise<Found[]> {
  const { sheets } = await getJsonNow<{ sheets: string[] }>(`/api/sheets/${enc(sheetId)}/tree`);
  const found = await Promise.all([sheetId, ...sheets].map((id) => searchSheet(id, text)));
  return found.flat();
}
